// Kit v1 HDRIs (docs/kit.md): real captured night / overcast skies from the kit masters, for what the paint and the
// city's materials reflect. Files: web/public/assets/kit/hdri/ (generated by tools/assets/build_kit_hdri.py, 1K
// equirect: the renderer prefilters it into its 256-px PMREM cube).
//
// How they are used (no recompiles while driving: switching is uniforms and a texture node's value):
//  - driving: the reflection captures (the one-time city environment and the car's live probe) render the HDRI as
//    the sky (`capture` = 1 during those renders) while the main view keeps the game's own sky; the streets, lamps and
//    neon in the captures stay the real city's;
//  - garage: the room capture gets the HDRI added on top (Garage.setHdri), so the paint shows the room's light lines
//    and a night city;
//  - potato: the HDRI is the environment directly (no capture there).
// ?hdri=0 turns it all off (the look before the kit).
import * as THREE from 'three/webgpu';
import { HDRLoader } from 'three/examples/jsm/loaders/HDRLoader.js';
import { equirectUV, mix, positionWorldDirection, texture, uniform } from 'three/tsl';
import { pubUrl } from '../assetBase';

export interface KitHdriEntry { id: string; name: string; file: string; role: 'night' | 'overcast'; strength: number; licence: string }

const BASE = pubUrl('/assets/kit/hdri/');

/** which night HDRI a city reflects: street-level old towns, the neon skyline for the high-rise cities */
const NIGHT_FOR: Record<string, string> = {
  paris: 'cobblestone_street_night', lisbon: 'cobblestone_street_night', barcelona: 'cobblestone_street_night',
  madrid: 'cobblestone_street_night', amsterdam: 'cobblestone_street_night',
  london: 'hansaplatz', berlin: 'hansaplatz', melbourne: 'hansaplatz', sanfrancisco: 'hansaplatz',
};
const GARAGE_HDRI = 'shanghai_bund';

export function kitHdriOn(params: URLSearchParams) { return params.get('hdri') !== '0'; }

async function loadManifest(): Promise<KitHdriEntry[]> {
  try {
    const r = await fetch(BASE + 'manifest.json');
    if (!r.ok) return [];
    return ((await r.json()).hdris ?? []) as KitHdriEntry[];
  } catch { return []; }
}

async function loadTex(e: KitHdriEntry): Promise<THREE.DataTexture | null> {
  try {
    const t = await new HDRLoader().loadAsync(BASE + e.file);   // an LFS pointer stub fails to parse: null, the old look stays
    t.mapping = THREE.EquirectangularReflectionMapping;
    t.name = `kit_hdri_${e.id}`;
    return t;
  } catch (err) {
    console.warn('kit hdri: not loaded', e.id, err);
    return null;
  }
}

export class KitSky {
  /** 1 while a reflection capture renders: the sky drawn is the HDRI */
  readonly capture = uniform(0);
  readonly strength = uniform(1);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private texNode: any;   // the TSL typings do not chain texture nodes (the shader files use `any` the same way)
  private wrapped: unknown = null;

  private constructor(readonly night: THREE.DataTexture, readonly nightEntry: KitHdriEntry,
    readonly overcast: THREE.DataTexture | null, readonly overcastEntry: KitHdriEntry | null,
    readonly garage: THREE.DataTexture | null, readonly garageEntry: KitHdriEntry | null) {
    this.texNode = texture(night, equirectUV(positionWorldDirection));
    this.strength.value = nightEntry.strength;
  }

  static async load(cityId: string): Promise<KitSky | null> {
    const list = await loadManifest();
    const by = (id: string) => list.find((e) => e.id === id) ?? null;
    const nightEntry = by(NIGHT_FOR[cityId] ?? 'shanghai_bund') ?? list.find((e) => e.role === 'night') ?? null;
    if (!nightEntry) return null;
    const overcastEntry = list.find((e) => e.role === 'overcast') ?? null;
    const garageEntry = by(GARAGE_HDRI);
    const [night, overcast, garage] = await Promise.all([
      loadTex(nightEntry), overcastEntry ? loadTex(overcastEntry) : null,
      garageEntry && garageEntry !== nightEntry ? loadTex(garageEntry) : null,
    ]);
    if (!night) return null;
    return new KitSky(night, nightEntry, overcast, overcastEntry, garageEntry === nightEntry ? night : garage, garageEntry);
  }

  /** the garage HDRI's measured strength (its sky at the game's night-sky luminance) */
  get garageStrength() { return (this.garageEntry ?? this.nightEntry).strength; }

  /** the HDRI sky node (equirect lookup along the view direction, times the strength) */
  get skyNode() { return this.texNode.mul(this.strength); }

  /** Wrap the scene's sky: the game's own sky in the main view, the HDRI during captures. Idempotent. */
  wrapSky(scene: THREE.Scene) {
    if (scene.backgroundNode && scene.backgroundNode === this.wrapped) return;
    const base = scene.backgroundNode ?? null;
    if (!base) return;
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const node = mix(base as any, this.skyNode, this.capture);
    scene.backgroundNode = node;
    this.wrapped = node;
  }

  /** rain reflects the overcast sky (at its own, much lower strength), dry nights the city's night HDRI */
  setWeather(w: 'dry' | 'rain') {
    const rain = w === 'rain' && this.overcast && this.overcastEntry;
    this.texNode.value = rain ? this.overcast! : this.night;
    this.strength.value = rain ? this.overcastEntry!.strength : this.nightEntry.strength;
  }

  /** run `fn` (a capture render) with the HDRI as the sky */
  during<T>(fn: () => T): T {
    this.capture.value = 1;
    try { return fn(); } finally { this.capture.value = 0; }
  }
}
